alter table public.organizations enable row level security;
alter table public.profiles enable row level security;
alter table public.memberships enable row level security;
alter table public.classes enable row level security;
alter table public.curriculum_sources enable row level security;
alter table public.curriculum_items enable row level security;
alter table public.documents enable row level security;
alter table public.document_versions enable row level security;
alter table public.document_sources enable row level security;
alter table public.exercises enable row level security;
alter table public.assessments enable row level security;
alter table public.student_sheets enable row level security;
alter table public.progressions enable row level security;
alter table public.conversations enable row level security;
alter table public.conversation_messages enable row level security;
alter table public.generation_jobs enable row level security;
alter table public.exports enable row level security;
alter table public.subscriptions enable row level security;
alter table public.audit_events enable row level security;
create policy "organizations_select_member_or_super" on public.organizations for select using (public.is_organization_member(id) or public.is_super_admin());
create policy "organizations_insert_super" on public.organizations for insert with check (public.is_super_admin());
create policy "organizations_update_super_or_director" on public.organizations for update using (public.is_super_admin() or public.is_school_director(id)) with check (public.is_super_admin() or public.is_school_director(id));
create policy "organizations_delete_super" on public.organizations for delete using (public.is_super_admin());
create policy "profiles_select_own_or_org_or_super" on public.profiles for select using (id = auth.uid() or (organization_id is not null and public.is_organization_member(organization_id)) or public.is_super_admin());
create policy "profiles_update_own" on public.profiles for update using (id = auth.uid()) with check (id = auth.uid());
create policy "profiles_insert_self" on public.profiles for insert with check (id = auth.uid());
create policy "memberships_select_member_or_super" on public.memberships for select using (public.is_organization_member(organization_id) or public.is_super_admin());
create policy "memberships_insert_director_or_super" on public.memberships for insert with check (public.is_super_admin() or public.is_school_director(organization_id));
create policy "memberships_update_director_or_super" on public.memberships for update using (public.is_super_admin() or public.is_school_director(organization_id)) with check (public.is_super_admin() or public.is_school_director(organization_id));
create policy "memberships_delete_director_or_super" on public.memberships for delete using (public.is_super_admin() or public.is_school_director(organization_id));
create policy "classes_member_or_super" on public.classes for all using (public.is_organization_member(organization_id) or public.is_super_admin()) with check (public.is_organization_member(organization_id) or public.is_super_admin());
create policy "curriculum_sources_strict_read" on public.curriculum_sources for select using (status='published' or (organization_id is not null and public.is_organization_member(organization_id)) or public.is_super_admin());
create policy "curriculum_sources_manage" on public.curriculum_sources for all using (public.is_super_admin() or public.is_referential_admin()) with check (public.is_super_admin() or public.is_referential_admin());
create policy "curriculum_items_read" on public.curriculum_items for select using (exists (select 1 from public.curriculum_sources s where s.id = source_id and (s.status='published' or (s.organization_id is not null and public.is_organization_member(s.organization_id)) or public.is_super_admin())));
create policy "curriculum_items_manage" on public.curriculum_items for all using (public.is_super_admin() or public.is_referential_admin()) with check (public.is_super_admin() or public.is_referential_admin());
create policy "documents_strict_isolation" on public.documents for all using (owner_id = auth.uid() or public.is_organization_member(organization_id) or public.is_super_admin()) with check (owner_id = auth.uid() or public.is_organization_member(organization_id) or public.is_super_admin());
create policy "document_versions_strict" on public.document_versions for all using (exists (select 1 from public.documents d where d.id = document_id and (d.owner_id = auth.uid() or public.is_organization_member(d.organization_id) or public.is_super_admin()))) with check (exists (select 1 from public.documents d where d.id = document_id and (d.owner_id = auth.uid() or public.is_organization_member(d.organization_id) or public.is_super_admin())));
create policy "document_sources_strict" on public.document_sources for all using (exists (select 1 from public.documents d where d.id = document_id and (d.owner_id = auth.uid() or public.is_organization_member(d.organization_id) or public.is_super_admin()))) with check (exists (select 1 from public.documents d where d.id = document_id and (d.owner_id = auth.uid() or public.is_organization_member(d.organization_id) or public.is_super_admin())));
create policy "exercises_strict" on public.exercises for all using (owner_id = auth.uid() or public.is_organization_member(organization_id) or public.is_super_admin()) with check (owner_id = auth.uid() or public.is_organization_member(organization_id) or public.is_super_admin());
create policy "assessments_strict" on public.assessments for all using (owner_id = auth.uid() or public.is_organization_member(organization_id) or public.is_super_admin()) with check (owner_id = auth.uid() or public.is_organization_member(organization_id) or public.is_super_admin());
create policy "student_sheets_strict" on public.student_sheets for all using (owner_id = auth.uid() or public.is_organization_member(organization_id) or public.is_super_admin()) with check (owner_id = auth.uid() or public.is_organization_member(organization_id) or public.is_super_admin());
create policy "progressions_strict" on public.progressions for all using (owner_id = auth.uid() or public.is_organization_member(organization_id) or public.is_super_admin()) with check (owner_id = auth.uid() or public.is_organization_member(organization_id) or public.is_super_admin());
create policy "conversations_strict_owner" on public.conversations for all using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy "conversation_messages_strict_owner" on public.conversation_messages for all using (exists (select 1 from public.conversations c where c.id = conversation_id and c.user_id = auth.uid())) with check (exists (select 1 from public.conversations c where c.id = conversation_id and c.user_id = auth.uid()));
create policy "generation_jobs_strict" on public.generation_jobs for all using (requested_by = auth.uid() or public.is_organization_member(organization_id) or public.is_super_admin()) with check (requested_by = auth.uid() or public.is_organization_member(organization_id) or public.is_super_admin());
create policy "exports_strict" on public.exports for all using (public.is_organization_member(organization_id) or public.is_super_admin()) with check (public.is_organization_member(organization_id) or public.is_super_admin());
create policy "subscriptions_strict" on public.subscriptions for all using (public.is_organization_member(organization_id) or public.is_super_admin()) with check (public.is_organization_member(organization_id) or public.is_super_admin());
create policy "audit_events_read_super" on public.audit_events for select using (public.is_super_admin());
create policy "audit_events_insert_any" on public.audit_events for insert with check (true);
create policy "curriculum_official_read_published" on storage.objects for select using (bucket_id='curriculum-official' and exists (select 1 from public.curriculum_sources s where s.file_path = name and s.status='published'));
create policy "curriculum_official_manage" on storage.objects for all using (bucket_id='curriculum-official' and (public.is_super_admin() or public.is_referential_admin())) with check (bucket_id='curriculum-official' and (public.is_super_admin() or public.is_referential_admin()));
create policy "teacher_documents_owner" on storage.objects for all using (bucket_id='teacher-documents' and owner = auth.uid()) with check (bucket_id='teacher-documents' and owner = auth.uid());
create policy "exports_member" on storage.objects for all using (bucket_id='exports' and exists (select 1 from public.exports e where e.file_path = name and (public.is_organization_member(e.organization_id) or public.is_super_admin()))) with check (bucket_id='exports' and exists (select 1 from public.exports e where e.file_path = name and (public.is_organization_member(e.organization_id) or public.is_super_admin())));
create or replace function public.log_sensitive_operation(p_action text,p_target_type text,p_target_id uuid,p_organization_id uuid,p_metadata jsonb default '{}'::jsonb) returns void language plpgsql security definer set search_path = public as $$ begin insert into public.audit_events (actor_id,organization_id,action,target_type,target_id,result,metadata) values (auth.uid(),p_organization_id,p_action,p_target_type,p_target_id,'success',p_metadata); end; $$;
create or replace function public.audit_document_changes() returns trigger language plpgsql security definer set search_path = public as $$ begin perform public.log_sensitive_operation(TG_OP,'document',NEW.id,NEW.organization_id,jsonb_build_object('title',NEW.title,'status',NEW.status)); return NEW; end; $$;
drop trigger if exists audit_documents on public.documents;
create trigger audit_documents after insert or update on public.documents for each row execute function public.audit_document_changes();
create or replace function public.audit_curriculum_changes() returns trigger language plpgsql security definer set search_path = public as $$ begin perform public.log_sensitive_operation(TG_OP,'curriculum_source',NEW.id,NEW.organization_id,jsonb_build_object('title',NEW.title,'version',NEW.version,'status',NEW.status)); return NEW; end; $$;
drop trigger if exists audit_curriculum_sources on public.curriculum_sources;
create trigger audit_curriculum_sources after insert or update on public.curriculum_sources for each row execute function public.audit_curriculum_changes();
